// so retorna itens onde o resultado MUDOU (vencida ou perdida) -- licitacoes
// ainda sem resultado publicado (o caso mais comum) sao filtradas aqui mesmo,
// nao precisam de nenhum processamento depois.
function normalizarCnpj(v) { return String(v || '').replace(/\D/g, ''); }

async function buscarJson(url) {
  try {
    return await this.helpers.httpRequest({ method: 'GET', url, json: true });
  } catch (e) {
    return null;
  }
}

const saida = [];
for (const item of $input.all()) {
  const r = item.json;
  const m = String(r.pncp_id || '').match(/^(\d{14})-\d+-(\d+)\/(\d{4})$/);
  if (!m) continue;
  const cnpjOrgao = m[1], sequencial = String(parseInt(m[2], 10)), ano = m[3];
  const itensUrl = 'https://pncp.gov.br/pncp-api/v1/orgaos/' + cnpjOrgao + '/compras/' + ano + '/' + sequencial + '/itens';
  const itens = await buscarJson.call(this, itensUrl);
  if (!Array.isArray(itens) || itens.length === 0) continue;

  const comResultado = itens.filter(i => i.temResultado === true);
  if (comResultado.length === 0) continue; // ainda pendente, nada a fazer

  const cnpjUsuario = normalizarCnpj(r.cnpj);
  let venceu = false;
  let vencedorInfo = null;
  for (const i of comResultado) {
    const resUrl = 'https://pncp.gov.br/pncp-api/v1/orgaos/' + cnpjOrgao + '/compras/' + ano + '/' + sequencial + '/itens/' + i.numeroItem + '/resultados';
    const resultados = await buscarJson.call(this, resUrl);
    if (!Array.isArray(resultados)) continue;
    const match = resultados.find(res => normalizarCnpj(res.niFornecedor) === cnpjUsuario && cnpjUsuario);
    if (match) { venceu = true; vencedorInfo = match; break; }
  }

  if (venceu) {
    saida.push({ json: { ...r, novo_resultado: 'vencida', valor_homologado: vencedorInfo.valorTotalHomologado } });
  } else if (comResultado.length === itens.length) {
    // todos os itens ja tem resultado publicado e o usuario nao apareceu em nenhum
    saida.push({ json: { ...r, novo_resultado: 'perdida' } });
  }
  // senao: alguns itens ainda sem resultado e usuario nao apareceu nos que ja tem --
  // continua pendente, tenta de novo no proximo ciclo (nao adiciona em "saida").
}
return saida;

const item = $input.first().json;
function formataValor(v) {
  if (v == null) return 'valor nao informado';
  return 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
}
const texto = '🎉 Voce venceu a licitacao "' + (item.objeto_resumo || item.pncp_id) + '"! Valor homologado: ' + formataValor(item.valor_homologado) + '. Ja vou preparar um rascunho de contrato pra voce revisar.';
return [{ json: { ...item, numero: (item.whatsapp_numero || '').replace(/\D/g, ''), texto } }];

